package services

import (
	"clawreef/internal/models"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"strings"
	"testing"
	"time"
)

// Cross-repository fixture is generated by the actual Runtime journal stage.
func TestRuntimeLargePublicDeliveryProjectsVisibleAuthenticatedArtifactReference(t *testing.T) {
	filename := os.Getenv("RUNTIME_PUBLIC_FIXTURE")
	if filename == "" {
		t.Skip("requires actual Runtime publication fixture")
	}
	raw, err := os.ReadFile(filename)
	if err != nil {
		t.Fatal(err)
	}
	var fixture struct {
		Event map[string]interface{} `json:"event"`
		Body  string                 `json:"body"`
	}
	if err := json.Unmarshal(raw, &fixture); err != nil {
		t.Fatal(err)
	}
	p := fixture.Event
	reference, text := eventString(p, "resultBodyRef"), eventString(p, "text")
	if !strings.HasPrefix(reference, "/team/results/") || !strings.Contains(text, "[Open complete answer]("+reference+")") {
		t.Fatal("full body is not linked through the authenticated Team workspace UI", p)
	}
	digest := sha256.Sum256([]byte(fixture.Body))
	if eventString(p, "resultBodySHA256") != hex.EncodeToString(digest[:]) || eventInt(p, "resultBodyBytes") != len([]byte(fixture.Body)) {
		t.Fatal("artifact integrity metadata differs from full body")
	}
	if len(text) > 4096 || p["textTruncated"] != false {
		t.Fatal("visible reference is missing or silently truncated")
	}
	now := time.Now().UTC()
	original := `{"completionId":"receipt","sourceMessageId":"original-input","summary":"done","resultMarkdown":"formal accepted answer","contentHash":"original-hash"}`
	repo := &teamRepositoryStub{workItems: []models.TeamWorkItem{{ID: 4, TeamID: 17, RootTaskID: 3, WorkID: "work", AssignmentID: stringPtr("work"), Revision: 1, OwnerMemberID: intPtr(2), Status: "succeeded", FinishedAt: &now, ResultJSON: &original}}}
	service := &teamService{repo: repo}
	task := &models.TeamTask{ID: 3, TeamID: 17, TargetMemberID: 1, Status: "succeeded", LedgerVersion: 4}
	member := &models.TeamMember{ID: 2, TeamID: 17, MemberKey: "worker", RuntimeType: "opencode"}
	if err := service.projectNativeDeliverySupplement(&models.Team{ID: 17}, nil, task, member, p, "20-0"); err != nil {
		t.Fatal(err)
	}
	if len(repo.createdEvents) != 1 {
		t.Fatal("actual CM projector silently omitted the supplement")
	}
	got := acknowledgedWorkItemContext(repo.workItems[0])
	if got["supplementaryText"] != text {
		t.Fatal("Leader/user-visible supplement differs from exact Runtime reference text", got)
	}
	eventPayload := teamEventPayloads(repo.createdEvents)[0].Payload
	if eventString(eventPayload, "text") != text || eventString(eventPayload, "resultBodyRef") != reference {
		t.Fatal("chat projection lost the visible body reference", eventPayload)
	}
}
